import api from './api';

const bookingApi = {
  getMovies() {
    // accept optional params object: { q, page, size }
    // callers may pass query params to use server-side search/pagination
    const args = Array.from(arguments);
    const params = args[0] || undefined;
    return api.get('/movies', params ? { params } : undefined);
  },
  getMovie(movieId) {
    return api.get(`/movies/${movieId}`);
  },
  getShowsForMovie(movieId) {
    // Primary: try to fetch shows for a movie.
    // If backend returns an empty payload (no shows yet) or the request fails,
    // callers in the UI expect a consistent shape. We return the axios promise
    // but resolve to a payload when possible so callers can rely on `res.data`.
    return api.get(`/movies/${movieId}/shows`).catch((err) => {
      throw err;
    });
  },
  getShow(showId) {
    return api.get(`/shows/${showId}`);
  },
  getSeatMap(showId) {
    // accept optional params argument: getSeatMap(showId, { q, page, size })
    const args = Array.from(arguments);
    const params = args[1] || undefined;
    return api.get(`/shows/${showId}/seats`, params ? { params } : undefined);
  },
  reserveSeats(showId, body) {
    return api.post(`/shows/${showId}/reserve`, body);
  },
  createOrder(body) {
    return api.post('/orders', body);
  },
  confirmOrder(orderId, body) {
    return api.post(`/orders/${orderId}/confirm`, body);
  },
  getOrder(orderId) {
    return api.get(`/orders/${orderId}`);
  },
};

export default bookingApi;
